// Exact Uniswap V3 math in BigInt for the HypurrSwap LP terminal. Ports of TickMath, FullMath,
// SqrtPriceMath (amount deltas) and LiquidityAmounts that match the deployed 0.7.6 libraries bit
// for bit (test/lpmath.test.mjs checks them against vectors generated by forge from the real code).
// Floats appear only in display helpers whose names say so (…Float); never in anything signed.

export const Q96 = 1n << 96n;
export const Q128 = 1n << 128n;
export const Q192 = 1n << 192n;
export const MAX_U256 = (1n << 256n) - 1n;
export const MAX_U128 = (1n << 128n) - 1n;
export const MIN_TICK = -887272;
export const MAX_TICK = 887272;
export const MIN_SQRT_RATIO = 4295128739n;
export const MAX_SQRT_RATIO = 1461446703485210103287273052203988822378723970342n;
export const TICK_SPACING = { 100: 1, 500: 10, 3000: 60, 10000: 200 };

const MOD256 = 1n << 256n;
const wrap256 = (v) => ((v % MOD256) + MOD256) % MOD256;

// ------------------------------------------------------------------------------------------
// FullMath
// ------------------------------------------------------------------------------------------

export function mulDiv(a, b, c) {
  if (c === 0n) throw new Error('mulDiv: zero denominator');
  const r = (a * b) / c;
  if (r > MAX_U256) throw new Error('mulDiv: overflow');
  return r;
}

export function mulDivRoundingUp(a, b, c) {
  const r = mulDiv(a, b, c);
  if ((a * b) % c > 0n) {
    if (r === MAX_U256) throw new Error('mulDivRoundingUp: overflow');
    return r + 1n;
  }
  return r;
}

const divRoundingUp = (a, b) => a / b + (a % b > 0n ? 1n : 0n);

function toUint128(v) {
  if (v > MAX_U128) throw new Error('toUint128: overflow');
  return v;
}

export function isqrt(n) {
  if (n < 0n) throw new Error('isqrt of negative');
  if (n < 2n) return n;
  let x = 1n << BigInt((n.toString(2).length + 1) >> 1);
  for (;;) { const y = (x + n / x) >> 1n; if (y >= x) return x; x = y; }
}

// ------------------------------------------------------------------------------------------
// TickMath
// ------------------------------------------------------------------------------------------

const TICK_FACTORS = [
  [0x2n, 0xfff97272373d413259a46990580e213an], [0x4n, 0xfff2e50f5f656932ef12357cf3c7fdccn],
  [0x8n, 0xffe5caca7e10e4e61c3624eaa0941cd0n], [0x10n, 0xffcb9843d60f6159c9db58835c926644n],
  [0x20n, 0xff973b41fa98c081472e6896dfb254c0n], [0x40n, 0xff2ea16466c96a3843ec78b326b52861n],
  [0x80n, 0xfe5dee046a99a2a811c461f1969c3053n], [0x100n, 0xfcbe86c7900a88aedcffc83b479aa3a4n],
  [0x200n, 0xf987a7253ac413176f2b074cf7815e54n], [0x400n, 0xf3392b0822b70005940c7a398e4b70f3n],
  [0x800n, 0xe7159475a2c29b7443b29c7fa6e889d9n], [0x1000n, 0xd097f3bdfd2022b8845ad8f792aa5825n],
  [0x2000n, 0xa9f746462d870fdf8a65dc1f90e061e5n], [0x4000n, 0x70d869a156d2a1b890bb3df62baf32f7n],
  [0x8000n, 0x31be135f97d08fd981231505542fcfa6n], [0x10000n, 0x9aa508b5b7a84e1c677de54f3e99bc9n],
  [0x20000n, 0x5d6af8dedb81196699c329225ee604n], [0x40000n, 0x2216e584f5fa1ea926041bedfe98n],
  [0x80000n, 0x48a170391f7dc42444e8fa2n],
];

export function getSqrtRatioAtTick(tick) {
  const t = Number(tick);
  if (!Number.isInteger(t) || t < MIN_TICK || t > MAX_TICK) throw new Error(`tick ${tick} out of range`);
  const abs = BigInt(Math.abs(t));
  let ratio = abs & 1n ? 0xfffcb933bd6fad37aa2d162d1a594001n : 0x100000000000000000000000000000000n;
  for (const [bit, f] of TICK_FACTORS) if (abs & bit) ratio = (ratio * f) >> 128n;
  if (t > 0) ratio = MAX_U256 / ratio;
  return (ratio >> 32n) + (ratio % (1n << 32n) === 0n ? 0n : 1n);
}

/// Greatest tick whose sqrt ratio is <= sqrtPriceX96: the definition the Solidity log2 code
/// implements. A binary search over the exact getSqrtRatioAtTick gives the same answer.
export function getTickAtSqrtRatio(sqrtPriceX96) {
  const s = BigInt(sqrtPriceX96);
  if (s < MIN_SQRT_RATIO || s >= MAX_SQRT_RATIO) throw new Error('sqrt ratio out of range');
  let lo = MIN_TICK, hi = MAX_TICK;
  while (lo < hi) {
    const mid = Math.floor((lo + hi + 1) / 2);
    if (getSqrtRatioAtTick(mid) <= s) lo = mid; else hi = mid - 1;
  }
  return lo;
}

// ------------------------------------------------------------------------------------------
// SqrtPriceMath amount deltas (what the pool really pulls on mint / pays on burn)
// ------------------------------------------------------------------------------------------

export function getAmount0Delta(a, b, liquidity, roundUp) {
  if (a > b) [a, b] = [b, a];
  if (a === 0n) throw new Error('sqrt ratio zero');
  const n1 = liquidity << 96n, n2 = b - a;
  return roundUp ? divRoundingUp(mulDivRoundingUp(n1, n2, b), a) : mulDiv(n1, n2, b) / a;
}

export function getAmount1Delta(a, b, liquidity, roundUp) {
  if (a > b) [a, b] = [b, a];
  return roundUp ? mulDivRoundingUp(liquidity, b - a, Q96) : mulDiv(liquidity, b - a, Q96);
}

// ------------------------------------------------------------------------------------------
// LiquidityAmounts (periphery)
// ------------------------------------------------------------------------------------------

export function getLiquidityForAmount0(a, b, amount0) {
  if (a > b) [a, b] = [b, a];
  return toUint128(mulDiv(amount0, mulDiv(a, b, Q96), b - a));
}

export function getLiquidityForAmount1(a, b, amount1) {
  if (a > b) [a, b] = [b, a];
  return toUint128(mulDiv(amount1, Q96, b - a));
}

export function getLiquidityForAmounts(p, a, b, amount0, amount1) {
  if (a > b) [a, b] = [b, a];
  if (p <= a) return getLiquidityForAmount0(a, b, amount0);
  if (p < b) {
    const l0 = getLiquidityForAmount0(p, b, amount0);
    const l1 = getLiquidityForAmount1(a, p, amount1);
    return l0 < l1 ? l0 : l1;
  }
  return getLiquidityForAmount1(a, b, amount1);
}

export function getAmount0ForLiquidity(a, b, l) {
  if (a > b) [a, b] = [b, a];
  return mulDiv(l << 96n, b - a, b) / a;
}

export function getAmount1ForLiquidity(a, b, l) {
  if (a > b) [a, b] = [b, a];
  return mulDiv(l, b - a, Q96);
}

export function getAmountsForLiquidity(p, a, b, l) {
  if (a > b) [a, b] = [b, a];
  if (p <= a) return [getAmount0ForLiquidity(a, b, l), 0n];
  if (p < b) return [getAmount0ForLiquidity(p, b, l), getAmount1ForLiquidity(a, p, l)];
  return [0n, getAmount1ForLiquidity(a, b, l)];
}

/// What UniswapV3Pool._modifyPosition charges for +L (mint, roundUp) or pays for -L (burn).
/// The pool branches on slot0.tick, not on the sqrt price.
export function amountsForDelta(sqrtP, tick, tickLower, tickUpper, l, roundUp) {
  const a = getSqrtRatioAtTick(tickLower), b = getSqrtRatioAtTick(tickUpper);
  if (tick < tickLower) return [getAmount0Delta(a, b, l, roundUp), 0n];
  if (tick < tickUpper) return [getAmount0Delta(sqrtP, b, l, roundUp), getAmount1Delta(a, sqrtP, l, roundUp)];
  return [0n, getAmount1Delta(a, b, l, roundUp)];
}

/// Exact mint preview: NonfungiblePositionManager computes L from the desired amounts with
/// LiquidityAmounts, then the pool pulls the rounded-up deltas for that L.
export function previewMint(sqrtP, tick, tickLower, tickUpper, amount0Desired, amount1Desired) {
  const a = getSqrtRatioAtTick(tickLower), b = getSqrtRatioAtTick(tickUpper);
  const liquidity = getLiquidityForAmounts(sqrtP, a, b, amount0Desired, amount1Desired);
  const [amount0, amount1] = liquidity === 0n ? [0n, 0n] : amountsForDelta(sqrtP, tick, tickLower, tickUpper, liquidity, true);
  return { liquidity, amount0, amount1 };
}

// ------------------------------------------------------------------------------------------
// Ticks, prices, decimals
// ------------------------------------------------------------------------------------------

export const minUsableTick = (s) => Math.ceil(MIN_TICK / s) * s;
export const maxUsableTick = (s) => Math.floor(MAX_TICK / s) * s;
export const clampTick = (t, s) => Math.min(maxUsableTick(s), Math.max(minUsableTick(s), t));
/// Rounds toward −∞ (Solidity's `/` truncates toward 0, which is wrong for negative ticks).
export const floorTick = (t, s) => clampTick(Math.floor(t / s) * s, s);
export const nearestTick = (t, s) => clampTick(Math.round(t / s) * s, s);

/// Parses a decimal string into an exact fraction [num, den]. Throws on anything else.
export function parseDecimal(str) {
  const m = /^\s*(\d*)(?:\.(\d*))?\s*$/.exec(String(str));
  if (!m || (m[1] === '' && (m[2] ?? '') === '')) throw new Error(`not a number: ${str}`);
  const frac = m[2] ?? '';
  return [BigInt((m[1] || '0') + frac), 10n ** BigInt(frac.length)];
}

/// Human price (token1 per 1 token0, as a decimal string) → sqrtPriceX96, floored. With
/// `invert` the string is token0 per 1 token1 instead (how the UI shows HYPE-quoted pairs).
export function priceToSqrtX96(price, d0, d1, invert = false) {
  let [num, den] = parseDecimal(price);
  if (num === 0n) throw new Error('price must be above zero');
  if (invert) [num, den] = [den, num];
  const s = isqrt((num * 10n ** BigInt(d1) * Q192) / (den * 10n ** BigInt(d0)));
  if (s < MIN_SQRT_RATIO || s >= MAX_SQRT_RATIO) throw new Error('price outside the V3 range');
  return s;
}

export const priceToTick = (price, d0, d1) => getTickAtSqrtRatio(priceToSqrtX96(price, d0, d1));

/// Display only: token1 per 1 token0 as a float.
export function sqrtToPriceFloat(sqrtX96, d0, d1) {
  const r = Number(sqrtX96) / 2 ** 96;
  return r * r * 10 ** (d0 - d1);
}
export const tickToPriceFloat = (tick, d0, d1) => 1.0001 ** tick * 10 ** (d0 - d1);

/// Value of (amount0, amount1) in token1 base units at sqrtP, exact (floored).
export const valueInToken1 = (amount0, amount1, sqrtP) => mulDiv(amount0, sqrtP * sqrtP, Q192) + amount1;
/// Value of (amount0, amount1) in token0 base units at sqrtP, exact (floored).
export const valueInToken0 = (amount0, amount1, sqrtP) => amount0 + mulDiv(amount1, Q192, sqrtP * sqrtP);

// ------------------------------------------------------------------------------------------
// Fees
// ------------------------------------------------------------------------------------------

/// UniswapV3Pool tick bookkeeping: fee growth inside [lower, upper], all mod 2^256.
export function feeGrowthInside({ tick, tickLower, tickUpper, global, outsideLower, outsideUpper }) {
  const below = tick >= tickLower ? outsideLower : wrap256(global - outsideLower);
  const above = tick < tickUpper ? outsideUpper : wrap256(global - outsideUpper);
  return wrap256(global - below - above);
}

/// Exactly what NonfungiblePositionManager.collect would pay for one token.
export function uncollectedFees({ liquidity, inside, insideLast, tokensOwed }) {
  return tokensOwed + mulDiv(wrap256(inside - insideLast), liquidity, Q128);
}

// ------------------------------------------------------------------------------------------
// Value, impermanent loss vs HODL
// ------------------------------------------------------------------------------------------

/// Exact IL of a set of positions against holding what was deposited, at the current price.
/// legs: [{ amount0, amount1 }] now (fees excluded); deposited: { amount0, amount1 }.
/// Returns values in token1 base units and IL in parts-per-million (negative = loss).
export function ilVsHodl(now0, now1, dep0, dep1, sqrtP) {
  const lp = valueInToken1(now0, now1, sqrtP);
  const hodl = valueInToken1(dep0, dep1, sqrtP);
  const ppm = hodl === 0n ? 0n : ((lp - hodl) * 1_000_000n) / hodl;
  return { lp, hodl, ppm };
}

/// Illustration for the pre-deposit warning (float, labelled as math, never a forecast): value
/// of the position relative to holding, if the price is multiplied by k. Prices are in raw
/// token1/token0 units; ranges as ticks. Fees excluded.
export function ilScenarioFloat(tickLower, tickUpper, tick, k) {
  return shapeVsHodlFloat([{ tickLower, tickUpper, liquidity: 1n }], tick, k);
}

/// Same illustration for a multi-position shape: Σ V_LP / Σ V_HODL − 1 (values, not percentages).
export function shapeVsHodlFloat(legs, tick, k) {
  const p0 = 1.0001 ** tick, p = p0 * k;
  let lp = 0, hodl = 0;
  for (const leg of legs) {
    const pa = 1.0001 ** leg.tickLower, pb = 1.0001 ** leg.tickUpper, L = Number(leg.liquidity);
    const amt = (P) => { const c = Math.min(Math.max(P, pa), pb); return [1 / Math.sqrt(c) - 1 / Math.sqrt(pb), Math.sqrt(c) - Math.sqrt(pa)]; };
    const [x0, y0] = amt(p0), [x, y] = amt(p);
    lp += L * (p * x + y); hodl += L * (p * x0 + y0);
  }
  return hodl === 0 ? 0 : lp / hodl - 1;
}

/// How much to swap before minting [tickLower, tickUpper] so the holdings fit the range's ratio
/// at sqrtP, after the pool fee (price impact ignored; the mint preview shows any leftover).
export function rebalanceSwap({ amount0, amount1, sqrtP, tickLower, tickUpper, fee }) {
  const [n0, n1] = getAmountsForLiquidity(sqrtP, getSqrtRatioAtTick(tickLower), getSqrtRatioAtTick(tickUpper), 1n << 80n);
  const P2 = sqrtP * sqrtP, keep = 1_000_000n - BigInt(fee), E6 = 1_000_000n;
  const lhs = amount0 * n1, rhs = n0 * amount1;
  if (lhs >= rhs) {
    const den = n1 * Q192 * E6 + n0 * P2 * keep;
    return { zeroForOne: true, amountIn: den === 0n ? 0n : ((lhs - rhs) * Q192 * E6) / den };
  }
  const den = n0 * P2 * E6 + n1 * keep * Q192;
  return { zeroForOne: false, amountIn: den === 0n ? 0n : ((rhs - lhs) * P2 * E6) / den };
}

/// A range of the same width as [tickLower, tickUpper], re-centred on the current tick.
export function recentre(tickLower, tickUpper, tick, spacing) {
  const w = tickUpper - tickLower, centre = floorTick(tick, spacing);
  const lo = clampTick(centre - Math.floor(w / 2 / spacing) * spacing, spacing);
  return [lo, clampTick(lo + w, spacing)];
}

// ------------------------------------------------------------------------------------------
// Strategy splitter (Meteora-style shapes built from V3 positions)
// ------------------------------------------------------------------------------------------

const UNIT_L = 1n << 80n;

/// Splits a deposit into V3 positions for a shape. The legs' desired amounts always sum
/// exactly to (amount0, amount1); rounding remainders go to the last leg that can use the
/// token (or the last leg when none can, so nothing is silently dropped).
///   kind 'spot'   one position [lower, upper]
///   kind 'curve'  n nested positions centred on the price, equal L each, so the summed L
///                 steps down away from the price (more weight near the price)
///   kind 'bidask' n adjacent single-sided positions per side, L growing towards the edges:
///                 bids (token1) below the price, asks (token0) above
/// Ticks are already multiples of `spacing`; `tick` and `sqrtP` come from slot0.
export function splitStrategy({ kind, amount0, amount1, sqrtP, tick, spacing, lower, upper, n = 1 }) {
  if (amount0 < 0n || amount1 < 0n) throw new Error('negative deposit');
  lower = clampTick(lower, spacing); upper = clampTick(upper, spacing);
  if (lower % spacing || upper % spacing) throw new Error('range must be on tick spacing');
  if (lower >= upper) throw new Error('range lower must be below upper');
  n = Math.max(1, Math.min(10, Math.floor(n)));
  let ranges = [];
  if (kind === 'spot') ranges = [[lower, upper, 1n]];
  else if (kind === 'curve') {
    const centre = floorTick(tick, spacing);
    if (!(lower <= centre && centre < upper)) throw new Error('Curve needs a range around the current price');
    const left = (centre - lower) / spacing, right = (upper - centre) / spacing;
    for (let i = 1; i <= n; i++) {
      const lo = centre - Math.round((left * i) / n) * spacing;
      const hi = centre + Math.max(1, Math.round((right * i) / n)) * spacing;
      const r = [clampTick(lo, spacing), clampTick(hi, spacing), 1n];
      if (!ranges.some((x) => x[0] === r[0] && x[1] === r[1])) ranges.push(r);
    }
  } else if (kind === 'bidask') {
    const below = floorTick(tick, spacing); // first boundary at or below the price
    const above = below + spacing;          // first boundary strictly above the price's tick
    const sides = [];
    if (amount1 > 0n && lower < below) sides.push([lower, Math.min(below, upper), 'bid']);
    if (amount0 > 0n && upper > above) sides.push([Math.max(above, lower), upper, 'ask']);
    for (const [lo, hi, side] of sides) {
      const steps = (hi - lo) / spacing, k = Math.min(n, steps);
      for (let i = 0; i < k; i++) {
        const a = lo + Math.floor((steps * i) / k) * spacing, b = lo + Math.floor((steps * (i + 1)) / k) * spacing;
        // Weight grows with distance from the price: bids heaviest at the bottom, asks at the top.
        const w = BigInt(side === 'bid' ? k - i : i + 1);
        ranges.push([a, b, w]);
      }
    }
    if (!ranges.length) ranges = [[lower, upper, 1n]];
  } else throw new Error(`unknown strategy ${kind}`);

  // Each leg's need per unit of weighted L at the current price.
  const need = ranges.map(([lo, hi, w]) => {
    const [x, y] = getAmountsForLiquidity(sqrtP, getSqrtRatioAtTick(lo), getSqrtRatioAtTick(hi), UNIT_L);
    return [x * w, y * w];
  });
  const split = (total, idx) => {
    const sum = need.reduce((s, x) => s + x[idx], 0n);
    const out = need.map((x) => (sum === 0n ? 0n : (total * x[idx]) / sum));
    let last = need.length - 1;
    if (sum > 0n) while (need[last][idx] === 0n) last--;
    out[last] += total - out.reduce((s, x) => s + x, 0n);
    return out;
  };
  const a0 = split(amount0, 0), a1 = split(amount1, 1);
  return ranges.map(([tickLower, tickUpper, weight], i) => ({ tickLower, tickUpper, weight, amount0: a0[i], amount1: a1[i] }));
}

/// Amount of the other token to pair with `amount` of one token so the shape uses both fully
/// (in-range legs). Returns 0 when the shape needs only the given token.
export function pairedAmount({ kind, sqrtP, tick, spacing, lower, upper, n, side, amount }) {
  const probe = splitStrategy({ kind, amount0: 1n << 120n, amount1: 1n << 120n, sqrtP, tick, spacing, lower, upper, n });
  let need0 = 0n, need1 = 0n;
  for (const l of probe) {
    const [x, y] = getAmountsForLiquidity(sqrtP, getSqrtRatioAtTick(l.tickLower), getSqrtRatioAtTick(l.tickUpper), UNIT_L * l.weight);
    need0 += x; need1 += y;
  }
  if (side === 0) return need0 === 0n ? 0n : (amount * need1) / need0;
  return need1 === 0n ? 0n : (amount * need0) / need1;
}
